"use server";

/**
 * Player-inventory editor for free-tier Minecraft servers (Players tab).
 *
 * IMPORTANT LIMITATION, by design: vanilla RCON has no "read a player's
 * current inventory" command. The only inventory primitive available is the
 * WRITE-only `/item replace entity <player> <slot> with <item>[<count>]`
 * (stable since 1.19, confirmed current for 26.x). There is therefore no way
 * to show what a slot currently holds — this is a "set this slot to become
 * X" tool, not a live view+edit of contents. The client component is
 * explicit about that; this file never claims to read inventory state.
 *
 * `with air` (no count) clears a slot, equivalent to deleting whatever was
 * there — used here whenever the caller picks the "(Empty / clear slot)"
 * catalog entry.
 *
 * Every value that reaches the RCON command string is validated against a
 * fixed allowlist first (slot names, item ids, integer count range) — same
 * "reject, never sanitize" posture as lib/ssh-exec.ts and validateRconCommand
 * in lib/game-control.ts. The item id and slot name are NEVER taken as free
 * text; both must exactly match a known-good value or the whole submission
 * is rejected before anything touches the SSH connection.
 */
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { withServerSsh, exec } from "./ssh-exec";
import type { SftpServer } from "./sftp";
import { sendRcon, getFreeServerPlayers } from "./free-minecraft-control";
import { isKnownMinecraftItemId } from "./minecraft-items";

/** Same lookup pattern as freemcHost() in lib/actions-free-minecraft.ts —
 *  that helper isn't exported, so it's reproduced here rather than reaching
 *  into another module's internals. */
async function freemcHost(): Promise<SftpServer> {
  const host = await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  });
  if (!host) throw new Error("Free Minecraft host is not provisioned.");
  return host;
}

/** The exact slot vocabulary `/item replace entity` accepts — nothing else
 *  is a legal slot argument, so anything not in this set is rejected outright. */
const VALID_SLOTS = new Set<string>([
  "weapon.mainhand",
  "weapon.offhand",
  "armor.head",
  "armor.chest",
  "armor.legs",
  "armor.feet",
  ...Array.from({ length: 36 }, (_, i) => `inventory.${i}`),
  ...Array.from({ length: 9 }, (_, i) => `hotbar.${i}`),
]);

/** Vanilla Minecraft username charset (offline-mode names, which is what
 *  this fleet runs with ONLINE_MODE=FALSE, follow the same rules). */
const PLAYER_NAME_RE = /^[A-Za-z0-9_]{1,16}$/;

export type InventoryEditRequest = { slot: string; itemId: string; count: number };
export type InventoryEditResult = { slot: string; ok: boolean; message: string };
export type ApplyInventoryEditState = {
  error?: string;
  results?: InventoryEditResult[];
};

/** Parse+validate the raw JSON payload the client posts. Never trusts shape
 *  or content — every field is re-checked against its allowlist here. */
function parseEdits(raw: string): { ok: true; edits: InventoryEditRequest[] } | { ok: false; error: string } {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return { ok: false, error: "Malformed submission." };
  }
  if (!Array.isArray(parsed) || parsed.length === 0) {
    return { ok: false, error: "Pick at least one slot to change." };
  }
  if (parsed.length > VALID_SLOTS.size) {
    return { ok: false, error: "Too many slot changes in one submission." };
  }

  const edits: InventoryEditRequest[] = [];
  for (const raw of parsed) {
    if (typeof raw !== "object" || raw === null) return { ok: false, error: "Malformed slot entry." };
    const slot = String((raw as Record<string, unknown>).slot ?? "");
    const itemId = String((raw as Record<string, unknown>).itemId ?? "");
    const countRaw = (raw as Record<string, unknown>).count;
    const count = typeof countRaw === "number" ? countRaw : Number(countRaw);

    if (!VALID_SLOTS.has(slot)) return { ok: false, error: `Unknown slot: ${slot}` };
    if (!isKnownMinecraftItemId(itemId)) return { ok: false, error: `Unknown item: ${itemId}` };
    if (!Number.isInteger(count) || count < 1 || count > 64) {
      return { ok: false, error: `Count for ${slot} must be a whole number from 1 to 64.` };
    }
    edits.push({ slot, itemId, count });
  }
  return { ok: true, edits };
}

/**
 * Applies one or more "set this slot to X" edits to a currently-online
 * player on the caller's own free server. Refuses outright if the target
 * isn't online right now — there's no server-side concept of "queue it for
 * next login" here, `/item replace entity` only affects an entity that
 * currently exists in the world.
 */
export async function applyPlayerInventoryEdit(
  _prev: ApplyInventoryEditState,
  formData: FormData,
): Promise<ApplyInventoryEditState> {
  const user = await requireUser();
  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
  if (!row) return { error: "You don't have a free server." };

  // One rate-limit hit per SUBMISSION (which may fire several RCON calls
  // server-side) — mirrors sendFreeMinecraftCommand's console rate limit,
  // just a bit tighter since a single submit can be multiple live commands.
  const rl = checkRateLimit(`freemc:inventory:${user.id}`, { max: 12, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };

  const requestedPlayer = String(formData.get("player") ?? "").trim();
  if (!PLAYER_NAME_RE.test(requestedPlayer)) return { error: "Pick a valid player." };

  const parsed = parseEdits(String(formData.get("edits") ?? ""));
  if (!parsed.ok) return { error: parsed.error };

  try {
    const host = await freemcHost();
    return await withServerSsh(host, async (conn) => {
      // Re-check online status server-side at submit time (the client's list
      // is just a UI convenience, not something we trust) and pull the
      // EXACT case the server currently knows the player by — Minecraft
      // target selectors match the live username, so use it, not whatever
      // case the caller happened to type or a stale dropdown value had.
      const online = await getFreeServerPlayers(conn, row.containerName, user.id);
      if (!online.ok) return { error: online.error || "Couldn't reach your server — is it asleep?" };
      const match = online.players.find((p) => p.name.toLowerCase() === requestedPlayer.toLowerCase());
      if (!match) return { error: `${requestedPlayer} isn't online right now — they need to be connected to receive items.` };

      const results: InventoryEditResult[] = [];
      for (const edit of parsed.edits) {
        const clearing = edit.itemId === "minecraft:air";
        const command = clearing
          ? `item replace entity ${match.name} ${edit.slot} with minecraft:air`
          : `item replace entity ${match.name} ${edit.slot} with ${edit.itemId} ${edit.count}`;
        const r = await sendRcon(conn, row.containerName, user.id, command);
        results.push({
          slot: edit.slot,
          ok: r.ok,
          message: r.ok ? r.response || "Applied." : r.error,
        });
      }
      return { results };
    });
  } catch (e) {
    console.error("[free-minecraft] inventory edit failed:", e);
    return { error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
  }
}

