import { db } from "/opt/nxeon-wt-invedit/lib/db";
import { withServerSsh, exec, shellQuote } from "/opt/nxeon-wt-invedit/lib/ssh-exec";
import type { SftpServer } from "/opt/nxeon-wt-invedit/lib/sftp";

const CONTAINER = "mc-invtest";
const RCON_PASSWORD = "invtest-throwaway-pw-1";

const SLOTS_TO_TEST = [
  "inventory.0",
  "inventory.8",
  "inventory.9",
  "inventory.26",
  "inventory.27",
  "inventory.35",
  "inventory.36",
  "hotbar.0",
  "hotbar.8",
  "hotbar.9",
  "armor.head",
  "armor.chest",
  "armor.legs",
  "armor.feet",
  "weapon.mainhand",
  "weapon.offhand",
  "enderchest.0",
];

async function main() {
  const host = (await db.server.findFirst({
    where: { hostname: "freemc-host" },
    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
  })) as SftpServer | null;
  if (!host) throw new Error("freemc-host not found");

  await withServerSsh(host, async (conn) => {
    for (const slot of SLOTS_TO_TEST) {
      const command = `item replace entity NonexistentPlayer1 ${slot} with minecraft:diamond 1`;
      const r = await exec(
        conn,
        `docker exec ${shellQuote(CONTAINER)} env RCON_PASSWORD=${shellQuote(RCON_PASSWORD)} rcon-cli ${shellQuote(command)}`,
        12_000,
      );
      console.log(`SLOT ${slot} -> code=${r.code} stdout=${JSON.stringify(r.stdout.trim())} stderr=${JSON.stringify(r.stderr.trim())}`);
    }

    console.log("\n--- clear-with-air test (no count) ---");
    const airCmd = `item replace entity NonexistentPlayer1 inventory.0 with minecraft:air`;
    const airR = await exec(
      conn,
      `docker exec ${shellQuote(CONTAINER)} env RCON_PASSWORD=${shellQuote(RCON_PASSWORD)} rcon-cli ${shellQuote(airCmd)}`,
      12_000,
    );
    console.log(`AIR -> code=${airR.code} stdout=${JSON.stringify(airR.stdout.trim())} stderr=${JSON.stringify(airR.stderr.trim())}`);
  });
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

/**
 * The exact slot vocabulary `/item replace entity <player> <slot> with ...`
 * accepts for a player entity. Live-verified against a real 26.2 vanilla
 * server (RCON `item replace entity <offline-name> <slot> with minecraft:diamond 1`
 * against a name that doesn't resolve, so any argument-parse failure surfaces
 * as "Unknown slot '<x>'" before entity resolution ever runs):
 *
 *   - inventory.0 .. inventory.26  (27 main-storage slots) — verified valid;
 *     inventory.27 returned "Unknown slot 'inventory.27'"
 *   - hotbar.0 .. hotbar.8  (9 hotbar slots) — verified valid;
 *     hotbar.9 returned "Unknown slot 'hotbar.9'"
 *   - armor.head / armor.chest / armor.legs / armor.feet — verified valid
 *   - weapon.mainhand / weapon.offhand — verified valid
 *
 * IMPORTANT CORRECTION: this is NOT "inventory.0 through inventory.35" as a
 * single combined range — that notation does not exist. The player's main
 * storage (27 slots) and hotbar (9 slots) are two SEPARATE slot namespaces
 * that together cover the same 36 physical slots a player has outside their
 * armor/offhand. `inventory.9`..`inventory.26` is main storage row 2/3/4,
 * NOT an alias for hotbar — confirmed on minecraft.wiki's Slot reference and
 * reproduced live above (inventory.27 is rejected, not silently accepted).
 *
 * `with air` (no count) is accepted as a valid item argument (clears the
 * slot) — also verified live: it parsed cleanly through to entity resolution
 * ("No entity was found") rather than failing as a bad command.
 *
 * Plain module (no "use server") — imported by both the server action
 * (lib/actions-freemc-inventory.ts, for validation) and the client component
 * (components/customer/freemc/InventoryEditor.tsx, to render the grid), so
 * there is exactly one definition of "what's a legal slot" rather than two
 * that could drift.
 */

export type SlotDef = { slot: string; label: string; group: "armor" | "hand" | "hotbar" | "main" };

export const ARMOR_SLOTS: SlotDef[] = [
  { slot: "armor.head", label: "Helmet", group: "armor" },
  { slot: "armor.chest", label: "Chestplate", group: "armor" },
  { slot: "armor.legs", label: "Leggings", group: "armor" },
  { slot: "armor.feet", label: "Boots", group: "armor" },
];

export const HAND_SLOTS: SlotDef[] = [
  { slot: "weapon.mainhand", label: "Main hand (currently-selected hotbar slot)", group: "hand" },
  { slot: "weapon.offhand", label: "Off hand", group: "hand" },
];

export const HOTBAR_SLOTS: SlotDef[] = Array.from({ length: 9 }, (_, i) => ({
  slot: `hotbar.${i}`,
  label: `Hotbar ${i + 1}`,
  group: "hotbar" as const,
}));

/** Main storage — 27 slots (3 rows of 9), verified as inventory.0-26. */
export const MAIN_INVENTORY_SLOTS: SlotDef[] = Array.from({ length: 27 }, (_, i) => ({
  slot: `inventory.${i}`,
  label: `Inventory ${i + 1}`,
  group: "main" as const,
}));

export const ALL_SLOTS: SlotDef[] = [...ARMOR_SLOTS, ...HAND_SLOTS, ...HOTBAR_SLOTS, ...MAIN_INVENTORY_SLOTS];

export const VALID_SLOT_NAMES: ReadonlySet<string> = new Set(ALL_SLOTS.map((s) => s.slot));

export function isValidSlotName(slot: string): boolean {
  return VALID_SLOT_NAMES.has(slot);
}

