12	 * explicit about that; this file never claims to read inventory state.
13	 *
14	 * `with air` (no count) clears a slot, equivalent to deleting whatever was
15	 * there — used here whenever the caller picks the "(Empty / clear slot)"
16	 * catalog entry.
17	 *
18	 * Every value that reaches the RCON command string is validated against a
19	 * fixed allowlist first (slot names, item ids, integer count range) — same
20	 * "reject, never sanitize" posture as lib/ssh-exec.ts and validateRconCommand
21	 * in lib/game-control.ts. The item id and slot name are NEVER taken as free
22	 * text; both must exactly match a known-good value or the whole submission
23	 * is rejected before anything touches the SSH connection.
24	 */
25	import { db } from "./db";
26	import { requireUser } from "./auth";
27	import { checkRateLimit } from "./rate-limit";
28	import { withServerSsh } from "./ssh-exec";
29	import type { SftpServer } from "./sftp";
30	import { sendRcon, getFreeServerPlayers } from "./free-minecraft-control";
31	import { isKnownMinecraftItemId } from "./minecraft-items";
32	import { isValidSlotName, ALL_SLOTS } from "./minecraft-slots";
33	
34	/** Same lookup pattern as freemcHost() in lib/actions-free-minecraft.ts —
35	 *  that helper isn't exported, so it's reproduced here rather than reaching
36	 *  into another module's internals. */
37	async function freemcHost(): Promise<SftpServer> {
38	  const host = await db.server.findFirst({
39	    where: { hostname: "freemc-host" },
40	    select: { id: true, rootPassword: true, rootPasswordEnc: true, sshPort: true, dedicatedIp: { select: { address: true } } },
41	  });
42	  if (!host) throw new Error("Free Minecraft host is not provisioned.");
43	  return host;
44	}
45	
46	/** Vanilla Minecraft username charset (offline-mode names, which is what
47	 *  this fleet runs with ONLINE_MODE=FALSE, follow the same rules). */
48	const PLAYER_NAME_RE = /^[A-Za-z0-9_]{1,16}$/;
49	
50	export type InventoryEditRequest = { slot: string; itemId: string; count: number };
51	export type InventoryEditResult = { slot: string; ok: boolean; message: string };
52	export type ApplyInventoryEditState = {
53	  error?: string;
54	  results?: InventoryEditResult[];
55	};
56	
57	/** Parse+validate the raw JSON payload the client posts. Never trusts shape
58	 *  or content — every field is re-checked against its allowlist here. */
59	function parseEdits(raw: string): { ok: true; edits: InventoryEditRequest[] } | { ok: false; error: string } {
60	  let parsed: unknown;
61	  try {
62	    parsed = JSON.parse(raw);
63	  } catch {
64	    return { ok: false, error: "Malformed submission." };
65	  }
66	  if (!Array.isArray(parsed) || parsed.length === 0) {
67	    return { ok: false, error: "Pick at least one slot to change." };
68	  }
69	  if (parsed.length > ALL_SLOTS.length) {
70	    return { ok: false, error: "Too many slot changes in one submission." };
71	  }
72	
73	  const edits: InventoryEditRequest[] = [];
74	  for (const raw of parsed) {
75	    if (typeof raw !== "object" || raw === null) return { ok: false, error: "Malformed slot entry." };
76	    const slot = String((raw as Record<string, unknown>).slot ?? "");
77	    const itemId = String((raw as Record<string, unknown>).itemId ?? "");
78	    const countRaw = (raw as Record<string, unknown>).count;
79	    const count = typeof countRaw === "number" ? countRaw : Number(countRaw);
80	
81	    if (!isValidSlotName(slot)) return { ok: false, error: `Unknown slot: ${slot}` };
82	    if (!isKnownMinecraftItemId(itemId)) return { ok: false, error: `Unknown item: ${itemId}` };
83	    if (!Number.isInteger(count) || count < 1 || count > 64) {
84	      return { ok: false, error: `Count for ${slot} must be a whole number from 1 to 64.` };
85	    }
86	    edits.push({ slot, itemId, count });
87	  }
88	  return { ok: true, edits };
89	}
90	
91	/**
92	 * Applies one or more "set this slot to X" edits to a currently-online
93	 * player on the caller's own free server. Refuses outright if the target
94	 * isn't online right now — there's no server-side concept of "queue it for
95	 * next login" here, `/item replace entity` only affects an entity that
96	 * currently exists in the world.
97	 */
98	export async function applyPlayerInventoryEdit(
99	  _prev: ApplyInventoryEditState,
100	  formData: FormData,
101	): Promise<ApplyInventoryEditState> {
102	  const user = await requireUser();
103	  const row = await db.freeMinecraftServer.findUnique({ where: { userId: user.id } });
104	  if (!row) return { error: "You don't have a free server." };
105	
106	  // One rate-limit hit per SUBMISSION (which may fire several RCON calls
107	  // server-side) — mirrors sendFreeMinecraftCommand's console rate limit,
108	  // just a bit tighter since a single submit can be multiple live commands.
109	  const rl = checkRateLimit(`freemc:inventory:${user.id}`, { max: 12, windowMs: 60_000 });
110	  if (!rl.ok) return { error: `Too many attempts — try again in ${rl.retryAfterSec}s.` };
111	
112	  const requestedPlayer = String(formData.get("player") ?? "").trim();
113	  if (!PLAYER_NAME_RE.test(requestedPlayer)) return { error: "Pick a valid player." };
114	
115	  const parsed = parseEdits(String(formData.get("edits") ?? ""));
116	  if (!parsed.ok) return { error: parsed.error };
117	
118	  try {
119	    const host = await freemcHost();
120	    return await withServerSsh(host, async (conn) => {
121	      // Re-check online status server-side at submit time (the client's list
122	      // is just a UI convenience, not something we trust) and pull the
123	      // EXACT case the server currently knows the player by — Minecraft
124	      // target selectors match the live username, so use it, not whatever
125	      // case the caller happened to type or a stale dropdown value had.
126	      const online = await getFreeServerPlayers(conn, row.containerName, user.id);
127	      if (!online.ok) return { error: online.error || "Couldn't reach your server — is it asleep?" };
128	      const match = online.players.find((p) => p.name.toLowerCase() === requestedPlayer.toLowerCase());
129	      if (!match) return { error: `${requestedPlayer} isn't online right now — they need to be connected to receive items.` };
130	
131	      const results: InventoryEditResult[] = [];
132	      for (const edit of parsed.edits) {
133	        const clearing = edit.itemId === "minecraft:air";
134	        const command = clearing
135	          ? `item replace entity ${match.name} ${edit.slot} with minecraft:air`
136	          : `item replace entity ${match.name} ${edit.slot} with ${edit.itemId} ${edit.count}`;
137	        const r = await sendRcon(conn, row.containerName, user.id, command);
138	        results.push({
139	          slot: edit.slot,
140	          ok: r.ok,
141	          message: r.ok ? r.response || "Applied." : r.error,
142	        });
143	      }
144	      return { results };
145	    });
146	  } catch (e) {
147	    console.error("[free-minecraft] inventory edit failed:", e);
148	    return { error: "Couldn't reach your server — is it asleep? Connect first to wake it up." };
149	  }
150	}
